"""Negative controls on actual complete .rbxlx generated by genuine pinned Rojo.

Unit tests intentionally mutate an in-memory copy of the file and assert
the exported Roblox script topology/source verifier rejects it.
"""
import copy
import os
from pathlib import Path
import sys
import unittest
import xml.etree.ElementTree as ET

TOOLS = Path(__file__).resolve().parents[1] / "tools"
sys.path.insert(0, str(TOOLS))
import verify_official_rojo_place as gate


class RojoPlaceMutationTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.place = Path(os.environ["P0D_REAL_ROJO_PLACE"]).read_bytes()
        cls.expected = gate.expected_rojo_source_paths()

    def mutate_xml(self, operation):
        root = ET.fromstring(self.place)
        operation(root)
        return ET.tostring(root, encoding="utf-8")

    def target(self, root, name):
        matches = [x for x in root.iter("Item") if gate.prop(x, "Name") == name]
        self.assertEqual(len(matches), 1, name)
        return matches[0]

    def test_actual_rojo_place_satisfies_manifest_source_topology(self):
        r = gate.verify_place(self.place)
        self.assertEqual(r["script_source_count"], 20)
        self.assertEqual(r["server_authority_script_count"], 1)
        self.assertEqual(r["local_script_count"], 3)
        self.assertEqual(r["module_script_count"], 16)
        self.assertFalse(r["roblox_studio_tested"])

    def test_actual_manifest_32_files_and_20_scripts(self):
        contents = gate.source_manifest()
        self.assertEqual(len(contents), 32)
        self.assertEqual(len(self.expected), 20)
        self.assertIn("src/server/Game.server.luau", contents)
        self.assertIn("src/client/HUD.client.luau", contents)

    def test_invalid_xml_is_rejected(self):
        with self.assertRaises(gate.VerificationError):
            gate.verify_place(b"<roblox><Item")

    def test_script_source_tampering_is_rejected(self):
        def mutate(root):
            item = self.target(root, "TrapRaidersHUD")
            props = item.find("Properties")
            entry = next(p for p in props if p.get("name") == "Source")
            entry.text = (entry.text or "") + "\n-- incorrect unpinned source"
        changed = self.mutate_xml(mutate)
        with self.assertRaisesRegex(gate.VerificationError, "ACTUAL_SCRIPT_BYTES_DIFFER"):
            gate.verify_place(changed)

    def test_second_Server_Game_authority_is_rejected(self):
        def mutate(root):
            item = self.target(root, "Game")
            parents = {child: parent for parent in root.iter() for child in parent}
            parents[item].append(copy.deepcopy(item))
        changed = self.mutate_xml(mutate)
        with self.assertRaises(gate.VerificationError):
            gate.verify_place(changed)

    def test_removing_player_client_HUD_is_rejected(self):
        def mutate(root):
            item = self.target(root, "TrapRaidersHUD")
            parents = {child: parent for parent in root.iter() for child in parent}
            parents[item].remove(item)
        changed = self.mutate_xml(mutate)
        with self.assertRaises(gate.VerificationError):
            gate.verify_place(changed)

    def test_removing_first_minute_tutorial_is_rejected(self):
        def mutate(root):
            item = self.target(root, "TrapRaidersCoach")
            parents = {child: parent for parent in root.iter() for child in parent}
            parents[item].remove(item)
        changed = self.mutate_xml(mutate)
        with self.assertRaises(gate.VerificationError):
            gate.verify_place(changed)

    def test_turning_Game_into_LocalScript_is_rejected(self):
        def mutate(root):
            item = self.target(root, "Game")
            item.attrib["class"] = "LocalScript"
        changed = self.mutate_xml(mutate)
        with self.assertRaises(gate.VerificationError):
            gate.verify_place(changed)

    def test_moving_Game_under_wrong_service_is_rejected(self):
        def mutate(root):
            item = self.target(root, "Game")
            other = self.target(root, "TrapRaidersShared")
            parents = {child: parent for parent in root.iter() for child in parent}
            parents[item].remove(item)
            other.append(item)
        changed = self.mutate_xml(mutate)
        with self.assertRaises(gate.VerificationError):
            gate.verify_place(changed)


if __name__ == "__main__":
    unittest.main(verbosity=2)
